const scoutFor=(t,o,dOrd,pt)=>{if(!t||!o)return null;if(_scoutMemo.k&&_scoutMemo.k[0]===t&&_scoutMemo.k[1]===o&&_scoutMemo.k[2]===dOrd&&_scoutMemo.k[3]===pt)return _scoutMemo.v;const ord=(x,mine)=>{const h=(x.roster||[]).filter(p=>!p.injured&&!p.holdout&&!p.suspended),m={};return pos=>m[pos]||(m[pos]=depthOrderFor(h,mine?dOrd||{}:{},pos,mine?pt:null));};let v=null;try{v=scoutReport(t,o,ord(t,true),ord(o,false));}catch{v=null;}_scoutMemo.k=[t,o,dOrd,pt];_scoutMemo.v=v;return v;};
