const PlayerTable=({players,setSel,sortCol,sortDir,onSort,posFilter,setPosFilter,showSign,onSign,onVetMin,onCompare,compareSlots,franchiseQB,depth})=>{
  const cols=[{k:"name",l:"Player",w:100},{k:"pos",l:"Pos",w:30},{k:"age",l:"Age",w:26},{k:"ovr",l:"OVR",w:30},{k:"pot",l:"POT",w:30},{k:"fit",l:"FIT",w:26},{k:"spd",l:"SPD",w:26},{k:"str",l:"STR",w:26},{k:"agi",l:"AGI",w:26},{k:"acc",l:"ACC",w:26},{k:"jmp",l:"JMP",w:26},{k:"end",l:"END",w:26},{k:"av",l:"AV",w:26},{k:"salary",l:"$M",w:32},{k:"contract",l:"Yr",w:22}];
  const filtered=posFilter==="ALL"?players:players.filter(p=>p.pos===posFilter);
  const sorted=[...filtered].sort((a,b)=>{const av=a[sortCol]??a.ss?.[sortCol]??0;const bv=b[sortCol]??b.ss?.[sortCol]??0;if(typeof av==="string")return -sortDir*av.localeCompare(bv);return sortDir*(av-bv);});
  return(<div>
    <div style={{display:"flex",gap:2,marginBottom:5,flexWrap:"wrap"}}>{["ALL",...POS].map(p=><button key={p} onClick={()=>setPosFilter(p)} style={{background:posFilter===p?C.bl+"33":"transparent",color:posFilter===p?"#fff":C.mt,border:`1px solid ${posFilter===p?C.bl:C.bd}`,padding:"4px 9px",borderRadius:4,fontSize:13,fontWeight:700,cursor:"pointer"}}>{p}</button>)}</div>
    <div style={{overflowX:"auto"}}><table style={{width:"100%",borderCollapse:"collapse",fontSize:14}}><thead><tr>
      <th style={{width:24,borderBottom:`1px solid ${C.bd}`}}></th>
      {cols.map(c=>[<th key={c.k} onClick={()=>onSort(c.k)} style={{cursor:"pointer",padding:"8px 4px",textAlign:"center",fontSize:12,color:sortCol===c.k?C.gn:C.mt,fontWeight:700,whiteSpace:"nowrap",width:c.w,borderBottom:`1px solid ${C.bd}`,background:C.bg}}>{c.l}{sortCol===c.k?(sortDir===-1?"▼":"▲"):""}</th>,c.k==="pos"&&depth&&<th key="depth" style={{width:64,padding:"8px 4px",fontSize:12,color:C.mt,fontWeight:700,borderBottom:`1px solid ${C.bd}`,background:C.bg,whiteSpace:"nowrap"}}>Depth</th>])}
      {showSign&&<th style={{width:36,borderBottom:`1px solid ${C.bd}`}}></th>}
      {onCompare&&<th style={{width:24,borderBottom:`1px solid ${C.bd}`}}></th>}
    </tr></thead><tbody>{sorted.map(p=><tr key={p.id} style={{borderBottom:`1px solid ${C.bd}66`,height:40}} onMouseOver={e=>e.currentTarget.style.background="#1e293b44"} onMouseOut={e=>e.currentTarget.style.background="transparent"}>
      <td style={{padding:"4px",textAlign:"center"}}><Face s={p.face} sz={28}/></td>
      <td style={{padding:"2px 6px",whiteSpace:"nowrap"}}>{p.injured&&<span style={{color:p.injSev==='major'?C.rd:p.injSev==='moderate'?"#f97316":"#eab308",fontSize:10,fontWeight:800,marginRight:1}}>{p.injSev==='major'?"MAJ":p.injSev==='moderate'?"MOD":"MIN"} </span>}<PN p={p} setSel={setSel}/>{p.xf&&<span title={`X-Factor: ${p.xf}`} style={{fontSize:9,background:'#f5c54222',color:'#f5c542',border:'1px solid #8a6d1d2e',borderRadius:3,padding:'0 4px',marginLeft:4,fontWeight:900}}>XF</span>}{p.fragile&&<span style={{fontSize:11,marginLeft:2}} title="Injury prone">IP</span>}{p.age<=24&&(p.pot||0)-p.ovr>=12&&<span style={{color:"#22d3ee",fontSize:10,fontWeight:800,marginLeft:2}}>↑</span>}{p.contract===1&&<span style={{fontSize:9,background:'#c4a235',color:'#000',borderRadius:2,padding:'1px 3px',fontWeight:700,marginLeft:2}}>CY</span>}{p.onBlock&&<span style={{fontSize:11,marginLeft:2}}>TB</span>}{p.rfaTender&&<span style={{fontSize:9,background:'#1e3a5f',color:'#7dd3fc',borderRadius:2,padding:'1px 3px',marginLeft:2}}>RFA</span>}</td>
      <td style={{textAlign:"center"}}><Bdg pos={posTag(p)}/></td>
      {depth&&<td style={{textAlign:"center",whiteSpace:"nowrap",fontSize:12,fontWeight:800,color:depth[p.id]?.starter?C.gn:"#64748b"}}>{depth[p.id]?.label||"—"}</td>}
      <td style={{textAlign:"center",color:p.age>31?"#f97316":"#94a3b8",fontSize:13}}>{p.age}</td>
      <td style={{textAlign:"center",fontWeight:800,color:oC(p.ovr)}}>{p.ovr}{p.devG>0&&<span style={{color:"#22d3ee",fontSize:10,marginLeft:2}}>+{p.devG}</span>}{p.devG<0&&<span style={{color:"#f97316",fontSize:10,marginLeft:2}}>{p.devG}</span>}{p.ftag&&<span style={{fontSize:10,background:"#b4530944",color:"#fef3c7",borderRadius:2,padding:"1px 3px",fontWeight:700,marginLeft:2}}>FT</span>}</td>
      <td style={{textAlign:"center",color:C.bl,fontWeight:700}}>{p.pot}</td>
      <td style={{textAlign:"center",fontSize:12,color:(p.fit||70)>=80?'#22c55e':(p.fit||70)>=60?'#eab308':'#ef4444',fontWeight:700}}>{p.fit||'—'}</td>
      <td style={{textAlign:"center",color:oC(p.spd),fontSize:12}}>{p.spd}</td>
      <td style={{textAlign:"center",color:oC(p.str),fontSize:12}}>{p.str}</td>
      <td style={{textAlign:"center",color:oC(p.agi),fontSize:12}}>{p.agi}</td>
      <td style={{textAlign:"center",color:oC(p.acc),fontSize:12}}>{p.acc}</td>
      <td style={{textAlign:"center",color:oC(p.jmp),fontSize:12}}>{p.jmp}</td>
      <td style={{textAlign:"center",color:oC(p.end),fontSize:12}}>{p.end}</td>
      <td style={{textAlign:"center",color:C.gd,fontWeight:700}}>{p.av}</td>
      <td style={{textAlign:"center",color:C.gd,fontSize:12}}>{typeof p.salary==="number"?`$${p.salary.toFixed(1)}`:"-"}{p.inc?.amt>0&&<span title={`Incentive: $${p.inc.amt}M for ${p.inc.label}`} style={{color:"#67e8f9",fontSize:9}}>★</span>}</td>
      <td style={{textAlign:"center",color:p.contract<=1?C.rd:C.mt,fontSize:12}}>{p.contract?`${p.contract}yr`:"FA"}</td>
      {showSign&&<td style={{display:"flex",gap:2,alignItems:"center"}}><Btn onClick={()=>onSign(p)} bg={`${C.gn}22`} c={C.gn} style={{border:`1px solid ${C.gn}44`,padding:"1px 5px",fontSize:11}}>Sign</Btn>{onVetMin&&p.ovr<=65&&<Btn onClick={()=>onVetMin(p)} bg="#14532d" c="#86efac" style={{padding:"1px 4px",fontSize:10}}>VET MIN</Btn>}</td>}
      {onCompare&&<td style={{textAlign:"center"}}><button onClick={()=>onCompare(p)} title="Compare" style={{background:(compareSlots||[]).some(x=>x.id===p.id)?'#7c3aed22':'transparent',color:(compareSlots||[]).some(x=>x.id===p.id)?'#a78bfa':'#475569',border:`1px solid ${(compareSlots||[]).some(x=>x.id===p.id)?'#7c3aed':'#334155'}`,borderRadius:2,padding:"1px 3px",fontSize:12,cursor:"pointer",lineHeight:1}}>vs</button></td>}
    </tr>)}</tbody></table></div>
  </div>);
};

