  const TABS=["dashboard","roster","schedule","scouting","stats","trade","freeagency","coaching","contracts","hub","trophies","saves","gameinfo"];
  const TAB_LABEL={dashboard:"Home",roster:"Roster",depth:"Depth Chart",schedule:"Schedule",standings:"Standings",stats:"Stats",scouting:"Scouting",draft:"Draft",trade:"Trade",freeagency:"Free Agency",coaching:"Coaching",growth:"Development",playoffs:"Playoffs",league:"League",hub:"Franchise History",wire:"Transactions",trophies:"Legacy Hall",records:"Record Book",history:"League History",draftrecap:"Draft Recap",contracts:"Front Office",saves:"Saves",gameinfo:"Game Updates",deadline:"Deadline Day",livesim:"Live Game",god:"God Mode",dev:"Balance"};
