    {extTalk&&ut&&(()=>{const p=ut.roster.find(x=>x.id===extTalk.id);if(!p)return null;const k=`ext:${yr}:${p.id}`;const loyalty=0.25+((ut?.w||0)>(ut?.l||0)?0.5:0);const t=talks[k]?.t||talkTerms(p,{yr,mode:"extend",loyalty,culture:hcCulture(ut?.coach?.hc)+(p.rookieAsk===yr&&sp==="combine"?0.08:0)/* signing early, before a breakout year, he takes less */});const startYr=yr+p.contract;return<Negotiate team={ut} cy={capYearFor(yr,sp)} p={p} mode="extend" cap={extRoom(ut,p,yr)} nowRoom={capSpace(ut)} t={t} talk={talks[k]||{}} note={`The new deal starts in ${startYr}, when his current contract runs out, so it has to fit under next season's cap. Walk away and he'll wait for re-sign week.`} onResult={(r,o)=>{setTalks(m=>({...m,[k]:{t,tries:r.tries,last:r,log:talkLog(m[k],o,r),walked:r.result==="walk",signed:r.result==="accept"}}));if(r.result==="accept"){setTeams(ts=>ts.map((tm,i)=>i!==ui?tm:{...tm,roster:tm.roster.map(x=>x.id===p.id?{...x,...(o.pr?{salary:+((x.salary||0)+o.pr).toFixed(1),sb:+(proration(x)+o.pr).toFixed(1)}:{}),ext:{sal:o.hit??o.sal,apy:o.sal,yrs:o.yrs,yr,...(o.pr?{sb:o.pr}:{})},holdout:false,holdoutStone:false,holdoutWks:0}:x)}));setLog(l=>[`EXTENDED: ${p.name} (${posTag(p)} ${p.ovr}) — ${o.yrs} yr${o.yrs>1?"s":""}, $${o.sal}M/yr starting ${startYr}${o.bonus?` ($${o.bonus}M signing bonus; cap hit $${o.hit}M a year)`:""}`,...l.slice(0,149)]);sm(`${p.name} extended: $${o.sal}M x ${o.yrs} from ${startYr}`);}}} onClose={()=>setExtTalk(null)}/>;})()}
