    {faBid&&<Dialog title="Bidding war" sub={`${faBid.player.name} (${faBid.player.pos} ${faBid.player.ovr}) has more than one suitor.`} actions={<><DBtn kind="primary" onClick={()=>{const winBid=+(faBid.aiOffer+0.5).toFixed(1);if(capSpace(ut||{})<winBid){sm('Not enough cap!');return;}const nt=[...teams];const _yrs=R(1,3);nt[ui]={...nt[ui],roster:[...nt[ui].roster,{...freshDeal(faBid.player),salary:winBid,contract:_yrs,...(sp==="freeagency"||sp==="draft"?{cy:yr+1}:{})}]};setTeams(nt);setFa(f=>f.filter(x=>x.id!==faBid.player.id));setWaivers(w=>w.filter(x=>x.id!==faBid.player.id));setFanSat(s=>cl(s+5,0,100));setFanSatLog(l=>[{delta:5,reason:'Bidding war win',wk},...l.slice(0,9)]);setLog(l=>[`BIDDING WAR: Signed ${faBid.player.name} for $${winBid}M (outbid ${faBid.aiTeamName})`,...l.slice(0,149)]);signMoment(faBid.player,nt[ui],_yrs,winBid);setFaBid(null);sm(`Won bidding war! Signed ${faBid.player.name}!`);}}>Outbid: ${(faBid.aiOffer+0.5).toFixed(1)}M/yr</DBtn><DBtn kind="danger" onClick={()=>{setLog(l=>[`Lost ${faBid.player.name} to ${faBid.aiTeamName} in bidding war`,...l.slice(0,149)]);const _bt=faBid.aiTid;if(_bt!=null)setTeams(ts=>ts.map((t,i)=>i!==_bt?t:{...t,roster:[...t.roster,{...freshDeal(faBid.player),salary:faBid.aiOffer,contract:2,...(sp==="freeagency"||sp==="draft"?{cy:yr+1}:{})}]}));setFa(f=>f.filter(x=>x.id!==faBid.player.id));setWaivers(w=>w.filter(x=>x.id!==faBid.player.id));setFanSat(s=>cl(s-3,0,100));setFaBid(null);sm(`Lost ${faBid.player.name} to ${faBid.aiTeamName}`);}}>Walk away</DBtn></>}><div style={softBox}><div style={{fontSize:15,fontWeight:800}}>The {faBid.aiTeamName} offer ${faBid.aiOffer}M a year</div><div style={{fontSize:14,color:C.mt,marginTop:4}}>Your cap space <b style={{color:capSpace(ut||{})>=(faBid.aiOffer+0.5)?C.gn:C.rd}}>${capSpace(ut||{}).toFixed(1)}M</b> · you need ${(faBid.aiOffer+0.5).toFixed(1)}M</div></div></Dialog>}
