    {tab==="coaching"&&(()=>{const ut=teams[ui];const staff=ut?.coach||{};const CoachCard=({coach,role,onFire,isHot})=>(<div style={{background:"#ffffff0d",borderRadius:18,padding:14,border:isHot?"1px solid #ef444488":0,display:"flex",flexWrap:"wrap",gap:8,alignItems:"flex-start"}}><Face s={coach.face} coach={coach.name} sz={36}/><div style={{flex:1,minWidth:0}}><div style={{fontWeight:800,fontSize:14,display:"flex",alignItems:"center",gap:4}}>{coach.name}{isHot&&<span style={{fontSize:10,background:"#7f1d1d",color:"#fca5a5",borderRadius:3,padding:"1px 4px",fontWeight:800}}>Hot seat</span>}</div><div style={{display:"flex",gap:4,marginTop:2,flexWrap:"wrap"}}><span style={{fontSize:11,background:`${C.bl}33`,color:C.bl,borderRadius:3,padding:"1px 4px"}}>{role}</span><span style={{fontSize:11,background:"#7c3aed33",color:"#a78bfa",borderRadius:3,padding:"1px 4px"}}>{coach.scheme}</span><span style={{fontSize:11,color:C.mt}}>{coach.trait}</span></div><div style={{display:"flex",gap:8,marginTop:4}}><span style={{fontSize:12,color:C.gn}}>RTG <b>{coach.rating}</b></span><span style={{fontSize:12,color:C.gd}}>$<b>{coach.salary}M</b></span><span style={{fontSize:11,color:C.mt}}>age {coachAge(coach,yr)}</span><span style={{fontSize:11,color:coach.contract<=1?C.rd:C.mt}}>{coach.contract||'?'}yr left</span></div>{/* his XP toward the next rating point, on his own card */}{role!=="HC"&&(()=>{const xp=(coach.xp||0)%20;return<div title="A win is 3 XP, a loss 1. Every 20 XP: +1 rating." style={{display:"flex",alignItems:"center",gap:6,marginTop:6}}><div style={{flex:1,height:4,background:"#1e293b",borderRadius:2,overflow:"hidden"}}><div style={{width:`${Math.round(xp/20*100)}%`,height:"100%",background:"#3b82f6"}}/></div><span style={{fontSize:11,color:C.mt,whiteSpace:"nowrap"}}>{xp}/20 XP</span></div>;})()}</div><OverflowMenu label={`More for ${coach.name}`} items={[{label:`Fire ${coach.name}`,danger:true,confirm:`Fire ${role} ${coach.name}? He goes into the coaching pool, where any club can hire him.`,onClick:onFire}]}/>{/* the actions sit in one row under the coach (they used to stack down the right side) */}<div style={{flexBasis:"100%",display:"flex",gap:6}}><Btn onClick={()=>upgradeCoach(role)} disabled={scPts<2||coach.rating>=95} bg="#ffffff0f" c="#cbd5e1" style={{flex:1,fontSize:12,padding:"7px 8px",borderRadius:8}}>Upgrade +5 · {scPts<2?"need 2 SP":"2 SP"}</Btn><Btn onClick={()=>setCoachExt(role)} disabled={scPts<1} bg="#ffffff0f" c="#cbd5e1" style={{flex:1,fontSize:12,padding:"7px 8px",borderRadius:8}}>Extend</Btn></div></div>);
    const EmptySlot=({role})=>(<div style={{background:C.cd,borderRadius:8,padding:10,border:`2px dashed ${C.bd}`,color:C.mt,fontSize:14,textAlign:"center"}}><div style={{fontWeight:700,marginBottom:2}}>{role} — Vacant</div><div style={{fontSize:11}}>Hire from available coaches below</div></div>);
    const FitBar=({val,max=4})=>{const pct=Math.round((val/max)*100);return<div style={{display:"flex",alignItems:"center",gap:4}}><div style={{flex:1,height:4,background:C.bd,borderRadius:2}}><div style={{width:`${pct}%`,height:"100%",background:val>=3?C.gn:val>=1.5?C.gd:C.rd,borderRadius:2}}/></div><span style={{fontSize:11,color:C.mt,minWidth:20}}>{val.toFixed(1)}</span></div>;};
    if(MOBILE)return<PhoneCoaching hcNote={hcLeaving(staff.hc)} hcExtOk={!staff.hc||hcExtMax(staff.hc,yr)>0} logo={ut} staff={staff} yr={yr} scPts={scPts} coachAge={coachAge} hcTrait={c=>HC_TRAITS[c.trait]||null} hcStyle={c=>styleLabel(coachAggression(c))} hotSeat={hotSeat} roster={ut?.roster||[]} faCoaches={faCoaches} cap={capSpace(ut)} gamePlan={gamePlanEl} clr={ut?.clr} onUpgrade={r=>upgradeCoach(r)} onExtend={r=>setCoachExt(r)} onFire={r=>fireCoach(r)} onHire={c=>hireCoach(c)} onMeeting={()=>{if(scPts<1){sm("Need 1 SP for Team Meeting");return;}setScPts(s=>s-1);const nt=[...teams];nt[ui].roster.forEach(p=>{p.conf=cl((p.conf||60)+5,0,100);});setTeams(nt);setLog(l=>["Team Meeting held — all conf +5",...l.slice(0,149)]);sm("Team Meeting: conf +5");}}/>;
    return<CoachingDesk staff={staff} yr={yr} scPts={scPts} coachAge={coachAge} hcTrait={c=>HC_TRAITS[c.trait]||null} hcStyle={c=>styleLabel(coachAggression(c))} hcNote={staff.hc&&hcLeaving(staff.hc)} hcExtOk={!staff.hc||hcExtMax(staff.hc,yr)>0} coy={staff.hc?awards.filter(a=>a.coy&&(a.coy.pid===staff.hc.id||a.coy.name===staff.hc.name)).map(a=>a.yr):[]} hotSeat={hotSeat} faCoaches={faCoaches} cap={capSpace(ut)} teams={teams} ui={ui} gamePlan={gamePlanEl} roster={ut?.roster||[]} onUpgrade={r=>upgradeCoach(r)} onExtend={r=>setCoachExt(r)} onFire={r=>fireCoach(r)} onHire={c=>hireCoach(c)} onMeeting={()=>{if(scPts<1){sm("Need 1 SP for Team Meeting");return;}setScPts(s=>s-1);const nt=[...teams];nt[ui].roster.forEach(p=>{p.conf=cl((p.conf||60)+5,0,100);});setTeams(nt);setLog(l=>["Team Meeting held — all conf +5",...l.slice(0,149)]);sm("Team Meeting: conf +5");}}/>;})()}

