    {paperOpen&&(paperOpen.kind==='champ'?<ChampionGazette show={paperOpen.cel} teams={teams.map((t,i)=>paperOpen.snap?.[i]?{...t,...paperOpen.snap[i]}:t)} ui={ui} path={paperOpen.cel.path} titles={paperOpen.cel.titles} repeat={paperOpen.cel.repeat} streak={paperOpen.cel.streak} cta="Close the paper" onNext={()=>setPaperOpen(null)}/>:<PlayoffPaper paper={paperOpen} onClose={()=>setPaperOpen(null)}/>)}
